-- GameXS editorial overviews, part 5 (ps5_games.overview, migration 040).
--
-- Same format and rules as db/content/game_overviews.sql: original Persian copy
-- written for GameXS; facts checked against the IGDB data stored in ps5_games.
--
-- Shape: {"intro", "suits": [..], "sections": [{"heading", "paragraphs": [..], "media"}]}
-- media = "trailer" | "screenshot:N" (1-based index into screenshot_ids); a key
-- the game has no asset for is skipped at render time.
--
-- Idempotent: re-running overwrites the overview of each listed slug and
-- touches nothing else. Apply with:
--   docker exec -i gamexs-postgres psql -U gamexs -d gamexs -v ON_ERROR_STOP=1 < db/content/game_overviews_part5.sql

UPDATE ps5_games g
SET overview = v.overview::jsonb
FROM (VALUES

('resident-evil-village', $j${
  "intro": "Resident Evil Village ادامه مستقیم Resident Evil 7 است و دوباره ایتن وینترز را در قالب یک بازی وحشت بقای اول‌شخص به دل کابوس می‌فرستد. Capcom این بار فضای خانه متروکه را کنار گذاشته و بازیکن را به روستایی برفی و دورافتاده در اروپای شرقی می‌برد؛ جایی پر از قلعه‌های گوتیک، موجودات عجیب و رازهایی قدیمی. نتیجه بازی‌ای است که ترس را با اکشن پررنگ‌تر و تنوع محیطی بیشتر ترکیب می‌کند.",
  "suits": ["طرفداران وحشت بقا", "علاقه‌مندان سری Resident Evil", "بازیکنان داستان‌محور"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "چند سال بعد از اتفاقات خانه بیکرها، ایتن و همسرش میا زندگی آرامی را از نو شروع کرده‌اند. اما یک شب کریس ردفیلد، چهره آشنای سری، به خانه آن‌ها حمله می‌کند و همه‌چیز را به هم می‌ریزد. ایتن برای پیدا کردن دخترش رز به روستایی کشیده می‌شود که زیر سلطه «مادر میراندا» و چهار ارباب عجیبش است.",
        "هر کدام از این اربابان، از لیدی دیمیترسکو و قلعه باشکوهش تا هایزنبرگ و کارخانه‌اش، بخش جداگانه‌ای از بازی را با سبک و نوع ترس متفاوتی شکل می‌دهند. همین تنوع باعث می‌شود Village مثل سفری از چند فیلم ترسناک مختلف به نظر برسد."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مثل نسخه‌های کلاسیک سری، باید محیط را برای مهمات، گیاهان درمانی و منابع بگردید و با فضای محدود کیف کنار بیایید. تفاوت اصلی با نسخه هفتم این است که دشمنان بیشتر و درگیری‌ها پرتعدادترند و سلاح‌ها نقش پررنگ‌تری دارند.",
        "تاجری به نام «دوک» در طول بازی به شما سلاح، ارتقا و آیتم می‌فروشد و با شکار حیوانات روستا می‌توانید برای ارتقای دائمی شخصیت غذا بپزید. معماها و راه‌های مخفی هم حس کشف را تا پایان زنده نگه می‌دارند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر از Resident Evil 7 خوشتان آمده اما کمی اکشن بیشتر می‌خواهید، Village انتخاب طبیعی بعدی است. بازی طولی متعادل دارد و بعد از پایان، حالت Mercenaries برای رکوردزنی و دلایل خوبی برای تجربه دوباره باقی می‌گذارد. برای کسانی که با سری آشنا نیستند هم داستان به‌قدر کافی مستقل است."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Resident Evil Village یک تجربه کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد و با محدودیت کمتری بازی کنید، ظرفیت ۲ انعطاف بیشتری دارد. قیمت روش‌های مختلف را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('watch-dogs-legion', $j${
  "intro": "Watch Dogs Legion سومین نسخه اصلی سری هکری Ubisoft است و این بار ماجرا را به لندن آینده نزدیک می‌برد؛ شهری که زیر سایه نظارت دائمی، شرکت‌های امنیتی خصوصی و گروه‌های تبهکار از دست مردم خارج شده است. ایده محوری بازی جسورانه است: قهرمان ثابتی وجود ندارد و تقریباً هر رهگذری در خیابان را می‌توانید به عضوی از گروه مقاومت تبدیل کنید.",
  "suits": ["علاقه‌مندان جهان‌باز شهری", "طرفداران مخفی‌کاری و هک", "بازیکنانی که آزادی عمل می‌خواهند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "بعد از یک سری انفجار در لندن، گروه هکری DedSec مقصر شناخته می‌شود و شهر به دست یک شرکت نظامی خصوصی می‌افتد. شما باید با عضوگیری از میان مردم عادی، مقاومت را از نو بسازید، پرده از هویت عامل اصلی انفجارها بردارید و محله‌های شهر را یکی‌یکی آزاد کنید.",
        "لندن بازی با بناهای شناخته‌شده، اتوبوس‌های دوطبقه، پهپادهای تحویل و تبلیغات هولوگرافیک، تصویری آشنا اما تیره از آینده نشان می‌دهد."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "هر شخصیت قابل عضوگیری پیشینه، شغل و مهارت‌های خودش را دارد؛ یک کارگر ساختمانی می‌تواند با پهپاد باربری روی ساختمان‌ها پرواز کند، یک مأمور امنیتی با لباس فرمش بدون جلب توجه وارد مناطق ممنوعه می‌شود و یک جاسوس سابق ابزارهای مخصوص خودش را دارد. برای جذب هر نفر هم معمولاً باید مأموریتی کوچک برایش انجام دهید.",
        "مأموریت‌ها را می‌شود با هک دوربین‌ها و ربات‌ها از راه دور، نفوذ بی‌صدا یا درگیری مستقیم پیش برد. گزینه مرگ دائمی هم وجود دارد که اگر فعال باشد، از دست دادن یک عضو گروه برای همیشه است و هر تصمیم را جدی‌تر می‌کند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "حالت‌های بازی",
      "paragraphs": [
        "بخش اصلی Legion داستان تک‌نفره است. در کنار آن یک حالت آنلاین هم به بازی اضافه شده که در آن می‌توانید با دوستانتان مأموریت‌های همکاری انجام دهید، اما بیشتر ارزش بازی در همان کمپین و گشت‌وگذار در لندن است."
      ],
      "media": "screenshot:6"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر فقط داستان را می‌خواهید، اکانت ظرفیت ۱ ارزان‌ترین انتخاب است، به شرط این‌که کنسول آفلاین بماند. برای سر زدن به بخش آنلاین، ظرفیت ۲ یا ۳ لازم است و بازی آنلاین روی PS5 معمولاً به اشتراک PS Plus نیاز دارد. ظرفیت ۲ هم آنلاین و هم آفلاین را پوشش می‌دهد. قیمت‌ها را در جدول همین صفحه ببینید."
      ]
    }
  ]
}$j$),

('collector-street-fighter-6-collectors-edition', $j${
  "intro": "این صفحه مربوط به نسخه کلکسیونی Street Fighter 6 است؛ ششمین نسخه اصلی سری مبارزه‌ای افسانه‌ای Capcom که با سه بخش اصلی، یعنی Fighting Ground، World Tour و Battle Hub، تلاش کرده هم برای حرفه‌ای‌ها و هم برای تازه‌واردها جذاب باشد. نسخه‌های کلکسیونی معمولاً اقلام فیزیکی ویژه‌ای کنار بازی دارند؛ محتوای دقیق را در صفحه فروشنده بررسی کنید.",
  "suits": ["طرفداران بازی‌های مبارزه‌ای", "کلکسیونرها", "بازیکنان رقابتی آنلاین"],
  "sections": [
    {
      "heading": "سه بخش اصلی بازی",
      "paragraphs": [
        "Fighting Ground قلب کلاسیک بازی است: مبارزه رودررو، حالت آرکید، تمرین و مسابقه رتبه‌بندی‌شده. World Tour یک حالت داستانی تک‌نفره است که در آن با شخصیت ساخت خودتان در Metro City و شهرهای دیگر می‌گردید، با استادان مبارزه آشنا می‌شوید و سبک آن‌ها را یاد می‌گیرید.",
        "Battle Hub هم فضایی آنلاین و اجتماعی است که بازیکنان با آواتارهایشان در آن جمع می‌شوند، پشت دستگاه‌های آرکید با هم مبارزه می‌کنند و حتی بازی‌های قدیمی Capcom را تجربه می‌کنند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "مبارزه چطور است؟",
      "paragraphs": [
        "سیستم Drive هسته مبارزات نسخه ششم است؛ نواری که با آن حرکاتی مثل Drive Impact، Drive Parry و Drive Rush را اجرا می‌کنید و مدیریت درستش تفاوت برد و باخت را رقم می‌زند. شخصیت‌های آشنایی مثل ریو، چون‌لی و کن در کنار چهره‌های تازه حضور دارند.",
        "برای تازه‌واردها دو سبک کنترل در نظر گرفته شده: Classic برای ورودی‌های سنتی سری و Modern که اجرای حرکات ویژه را با یک دکمه ساده‌تر می‌کند. به همین دلیل شروع بازی برای هر سطحی از تجربه دلگرم‌کننده است."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر به بازی‌های مبارزه‌ای علاقه دارید، Street Fighter 6 یکی از کامل‌ترین گزینه‌های PS5 است و نسخه کلکسیونی بیشتر برای کسانی جذاب است که به اقلام ویژه و ارزش نگهداری اهمیت می‌دهند. World Tour برای یادگیری و سرگرمی تک‌نفره خوب است، اما عمر طولانی بازی در رقابت آنلاین و مبارزه با دوستان است."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "نسخه کلکسیونی معمولاً به‌صورت فیزیکی عرضه می‌شود و مفهوم ظرفیت در آن مطرح نیست. اگر نسخه دیجیتال بازی را مقایسه می‌کنید، چون بخش بزرگی از جذابیت Street Fighter 6 در مسابقات آنلاین و Battle Hub است، اکانت ظرفیت ۱ مناسب نیست؛ ظرفیت ۲ یا ۳ را انتخاب کنید و در نظر داشته باشید که بازی آنلاین روی PS5 به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('jurassic-world-evolution-3', $j${
  "intro": "Jurassic World Evolution 3 سومین نسخه از سری شبیه‌ساز مدیریت پارک دایناسورهای Frontier Developments است. این بار شما نه فقط یک پارک، که پارک‌های بزرگی را در نقاط مختلف جهان می‌سازید و برای اولین بار در سری، دایناسورهای نوجوان و پرورش نسل‌های پیاپی هم به بازی اضافه شده‌اند. اگر رویای ساختن پارک ژوراسیک خودتان را دارید، این نسخه کامل‌ترین ابزار را در اختیارتان می‌گذارد.",
  "suits": ["علاقه‌مندان شبیه‌سازهای مدیریتی", "طرفداران دنیای Jurassic World", "بازیکنان خلاق و آرام"],
  "sections": [
    {
      "heading": "ایده اصلی بازی",
      "paragraphs": [
        "کار شما طراحی و اداره یک پارک دایناسور است؛ از ساخت آزمایشگاه و محوطه نگهداری تا راه‌ها، امکانات رفاهی و سیستم‌های امنیتی. باید هم رضایت بازدیدکنندگان را بالا نگه دارید و هم مراقب باشید دایناسورها گرسنه، ناراضی یا فراری نشوند.",
        "مهم‌ترین تازگی این نسخه چرخه زندگی دایناسورهاست. حالا می‌توانید شاهد بزرگ شدن نوزادان و نوجوانان باشید و نسل‌های مختلف را در پارک پرورش دهید، که به مدیریت گله‌ها عمق تازه‌ای می‌دهد."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی و ابزار ساخت",
      "paragraphs": [
        "مدیریت پارک در Evolution 3 ترکیبی از برنامه‌ریزی اقتصادی، پژوهش علمی و رسیدگی به بحران‌هاست. طوفان، قطعی برق یا فرار یک شکارچی بزرگ می‌تواند در چند دقیقه نظم پارک را به هم بریزد و شما باید سریع واکنش نشان دهید.",
        "ابزارهای ساخت‌وساز و شخصی‌سازی گسترده‌تر شده‌اند و دست شما برای طراحی پارک‌هایی با ظاهر دلخواه بازتر است. برای کسانی که فقط می‌خواهند خلاقیت به خرج دهند هم حالت‌های آزادتر در نظر گرفته شده است."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Jurassic World Evolution 3 بازی تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین بماند و از امکانات آنلاین آن استفاده کنید، ظرفیت ۲ انعطاف بیشتری دارد. قیمت روش‌های مختلف را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('shinobi-art-of-vengeance', $j${
  "intro": "Shinobi: Art of Vengeance بازگشت سری قدیمی و محبوب Shinobi از Sega است که پس از سال‌ها، با یک اکشن دوبعدی تازه به صحنه برگشته است. سازنده آن استودیو Lizardcube است؛ همان تیمی که Streets of Rage 4 را ساخت. بازی با گرافیک دست‌ساز و انیمیشن‌های روان، مبارزات سریع نینجایی را با مراحل پلتفرمر پر از راه مخفی ترکیب می‌کند.",
  "suits": ["طرفداران اکشن دوبعدی", "علاقه‌مندان بازی‌های کلاسیک Sega", "بازیکنانی که مبارزه سریع دوست دارند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شما در نقش جو موساشی، نینجای افسانه‌ای سری، بازی می‌کنید که بعد از حمله‌ای ویرانگر به قبیله‌اش، شمشیر افسانه‌ای «اوبوروزوکی» را برمی‌دارد تا انتقام بگیرد و جلوی شری بزرگ را بگیرد. داستان ساده و سرراست است و بیشتر بهانه‌ای برای سفر در محیط‌های متنوع و پر از هیولا و نینجای دشمن.",
        "سبک هنری دست‌کشیده بازی، از شهرهای نئونی تا جنگل‌ها و معابد، یکی از نقاط قوت اصلی آن است و حس احترام به نسخه‌های کلاسیک را با ظاهری مدرن ترکیب می‌کند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مبارزه بر پایه کمبوهای شمشیر، پرتاب شوریکن، حرکات هوایی و توانایی‌های ویژه نینجوتسو است. اجرای حرکت پایانی روی دشمنان ضعیف‌شده و زنجیر کردن ضربه‌ها، حس جریان و سرعت را به مبارزات می‌دهد.",
        "مراحل فقط مسیر خطی نیستند و با توانایی‌های تازه می‌توانید به بخش‌های پنهان برگردید و آیتم‌ها و ارتقاهای بیشتری پیدا کنید. باس‌فایت‌ها هم آزمونی جدی برای مهارت شما هستند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Shinobi: Art of Vengeance کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسول آنلاین باشد و دستتان بازتر باشد، ظرفیت ۲ انتخاب منعطف‌تری است. قیمت روش‌های مختلف را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('atomic-heart', $j${
  "intro": "Atomic Heart یک شوتر اول‌شخص ماجرایی از استودیو Mundfish است که در تاریخ جایگزینی از اتحاد جماهیر شوروی دهه ۱۹۵۰ می‌گذرد؛ دنیایی که در آن رباتیک و فناوری به اوج رسیده و ربات‌ها بخشی از زندگی روزمره شده‌اند. بازی با فضای رتروفوتوریستی خاص، دشمنان عجیب و مبارزات پرتنش، یکی از متفاوت‌ترین تجربه‌های اکشن سال‌های اخیر است.",
  "suits": ["طرفداران شوترهای داستانی", "علاقه‌مندان فضاهای رتروفوتوریستی", "بازیکنانی که سبک BioShock را دوست دارند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شما نقش مأمور ویژه‌ای با کد P-3 را بازی می‌کنید که به مجتمع علمی «۳۸۲۶» فرستاده می‌شود؛ جایی که ربات‌ها ناگهان از کنترل خارج شده‌اند و به انسان‌ها حمله می‌کنند. P-3 باید بفهمد چه اتفاقی افتاده و چه کسی پشت این فاجعه است.",
        "تضاد میان معماری باشکوه شوروی، شعارهای خوش‌بینانه و ربات‌هایی که به ماشین کشتار تبدیل شده‌اند، حال‌وهوای عجیب و گاهی طنزآلود بازی را می‌سازد. دستکشی سخنگو هم در تمام مسیر همراه و هم‌صحبت شخصیت اصلی است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مبارزات ترکیبی از سلاح‌های سرد، اسلحه‌های گرم و توانایی‌های ویژه دستکش است؛ توانایی‌هایی مثل شوک الکتریکی یا بلند کردن دشمنان با نیروی تله‌کینزی. سلاح‌ها و توانایی‌ها را می‌توانید با منابعی که جمع می‌کنید در ایستگاه‌های مخصوص ارتقا دهید.",
        "در کنار اکشن، بخش‌های اکتشافی، معماهای محیطی و آزمایشگاه‌های زیرزمینی اختیاری هم وجود دارد که با پاداش‌های ارزشمند، کنجکاوی را جبران می‌کنند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر شوترهایی مثل BioShock یا Prey را دوست دارید، Atomic Heart با دنیای جذاب و طراحی هنری خاصش ارزش تجربه دارد. سطح دشواری قابل تنظیم است و هم بازیکنانی که داستان می‌خواهند و هم کسانی که دنبال چالش هستند، می‌توانند آن را به دلخواه تجربه کنند."
      ],
      "media": "screenshot:8"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
