        "فیزیک توپ و برخوردها هم بازبینی شده‌اند تا شوت‌ها، پاس‌های بلند و دوئل‌ها حس واقعی‌تری داشته باشند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "حالت‌های بازی",
      "paragraphs": [
        "Ultimate Team همچنان پرطرفدارترین بخش بازی است؛ جایی که با کارت بازیکنان تیم رویایی‌تان را می‌سازید و در این نسخه بازیکنان مرد و زن می‌توانند در یک تیم کنار هم قرار بگیرند. قابلیت Evolutions هم اجازه می‌دهد کارت‌های محبوبتان را ارتقا دهید.",
        "Career Mode برای کسانی است که می‌خواهند در نقش مربی یا بازیکن، فصل‌به‌فصل پیش بروند. Clubs هم برای بازی گروهی آنلاین با دوستان در نظر گرفته شده و در کنار آن، مسابقه سریع آفلاین با دو دسته روی یک کنسول همیشه در دسترس است."
