      ]
    }
  ]
}$j$),

('cyberpunk-2077', $j${
  "intro": "Cyberpunk 2077 نقش‌آفرینی جهان‌باز CD Projekt RED، سازنده The Witcher 3، است که در نایت سیتی می‌گذرد؛ کلان‌شهری آینده‌نگر که با قدرت شرکت‌ها، تبهکاری و اصلاح بدن با ایمپلنت‌های سایبرنتیک اداره می‌شود. بازی بعد از عرضه پرحاشیه‌اش با به‌روزرسانی‌های بزرگ، به‌ویژه به‌روزرسانی 2.0، بازسازی جدی شد و امروز یکی از کامل‌ترین نقش‌آفرینی‌های نسل است.",
  "suits": ["طرفداران نقش‌آفرینی", "علاقه‌مندان داستان‌های علمی‌تخیلی", "بازیکنان جهان‌باز"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
