        "نایت سیتی با محله‌های متنوع، رانندگی، تعقیب‌وگریز و فعالیت‌های جانبی، شهری پرجزئیات و زنده است. سیستم مهارت‌ها و پیشرفت هم بعد از به‌روزرسانی‌ها بازطراحی شده و انتخاب‌های معنادارتری ارائه می‌دهد."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
