('call-of-duty-black-ops-cold-war', $j${
  "intro": "Call of Duty: Black Ops Cold War ادامه مستقیم Black Ops اول است که Treyarch آن را ساخته و Activision منتشر کرده است. بازی شما را به اوایل دهه ۱۹۸۰ و اوج جنگ سرد می‌برد و مثل همیشه سه بخش اصلی دارد: کمپین داستانی، چندنفره رقابتی و حالت محبوب زامبی‌ها.",
  "suits": ["طرفداران شوترهای نظامی", "بازیکنان چندنفره آنلاین", "علاقه‌مندان حالت زامبی"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
