  ]
}$j$),

('alan-wake-ii-deluxe-edition', $j${
  "intro": "Alan Wake II Deluxe Edition نسخه کامل‌تر ادامه Alan Wake از استودیو Remedy است؛ اولین تجربه این استودیو در سبک وحشت بقا. نسخه دلوکس علاوه بر بازی اصلی، بسته‌های الحاقی بعدی را هم شامل می‌شود. بازی با دو شخصیت اصلی، دو واقعیت موازی و روایتی که مرز داستان و حقیقت را به هم می‌ریزد، یکی از جاه‌طلبانه‌ترین بازی‌های داستانی نسل است.",
  "suits": ["طرفداران وحشت روانشناختی", "علاقه‌مندان روایت‌های پیچیده", "بازیکنان داستان‌محور"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
