('battlefield-4', $j${
  "intro": "Battlefield 4 شوتر نظامی پرآوازه استودیو DICE است که سال ۲۰۱۳ منتشر شد و هنوز هم بسیاری آن را یکی از بهترین نسخه‌های سری می‌دانند. نبردهای گسترده، خودروهای زمینی، هوایی و دریایی و تخریب‌پذیری محیط، Battlefield 4 را به نماد جنگ‌های بزرگ چندنفره تبدیل کرده است. این بازی برای نسل قبل ساخته شده و روی PS5 از طریق سازگاری با بازی‌های PS4 اجرا می‌شود.",
  "suits": ["طرفداران شوترهای نظامی", "بازیکنان چندنفره آنلاین", "علاقه‌مندان نبردهای بزرگ"],
  "sections": [
    {
      "heading": "کمپین داستانی",
      "paragraphs": [
        "کمپین داستان جوخه «تومب‌استون» را دنبال می‌کند؛ گروهی از نیروهای آمریکایی که در میانه تنش میان آمریکا، چین و روسیه گرفتار می‌شوند. شما در نقش سرباز رکر، از باکو تا شانگهای و نقاط دیگر می‌جنگید و تصمیم‌هایی می‌گیرید که در پایان ماجرا اثر دارند.",
        "کمپین کوتاه اما سینمایی است و بیشتر مقدمه‌ای برای بخش چندنفره به حساب می‌آید."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "چندنفره",
      "paragraphs": [
        "قلب Battlefield 4 بخش چندنفره است: نقشه‌های بزرگ، کلاس‌های مختلف سرباز، تانک، هلی‌کوپتر، جت و قایق. سیستم «Levolution» اجازه می‌دهد بخش‌های بزرگی از نقشه تغییر کند؛ مثلاً آسمان‌خراشی فرو بریزد یا سدی شکسته شود و شکل نبرد عوض شود.",
        "حالت‌های کلاسیکی مثل Conquest و Rush همچنان پایه بازی‌اند و همکاری با جوخه، از پزشک و مهندس تا تک‌تیرانداز، کلید پیروزی است."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "ارزش اصلی Battlefield 4 در بخش چندنفره آنلاین است، پس اکانت ظرفیت ۱ که فقط آفلاین کار می‌کند انتخاب مناسبی نیست. ظرفیت ۲ هم آنلاین و هم آفلاین را پوشش می‌دهد و ظرفیت ۳ ارزان‌ترین راه برای بازی آنلاین است. بازی آنلاین روی کنسول‌های پلی‌استیشن معمولاً به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('doom-eternal', $j${
  "intro": "Doom Eternal ادامه Doom سال ۲۰۱۶ از استودیو id Software است و یکی از سریع‌ترین و پرخشونت‌ترین شوترهای اول‌شخص سال‌های اخیر به حساب می‌آید. شما دوباره در نقش «دوم اسلیر» به جنگ ارتش جهنم می‌روید؛ این بار روی زمینی که شیاطین آن را تسخیر کرده‌اند.",
  "suits": ["طرفداران شوترهای سریع", "علاقه‌مندان موسیقی متال و اکشن", "بازیکنان چالش‌طلب"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "تهاجم شیاطین بخش بزرگی از جمعیت زمین را نابود کرده است. دوم اسلیر از قلعه‌ای ماهواره‌ای در مدار زمین بازمی‌گردد تا رهبران این تهاجم را یکی‌یکی از پا درآورد و به ریشه آن برسد.",
        "داستان در این نسخه پررنگ‌تر از قبل است و گذشته اسلیر و دنیای افسانه‌ای سری را بیشتر توضیح می‌دهد، اما همیشه در خدمت اکشن باقی می‌ماند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مبارزه در Doom Eternal مثل یک پازل سریع است. منابع از دشمنان به دست می‌آیند: با اعدام نزدیک دشمنان سلامت می‌گیرید، با اره‌برقی مهمات و با شعله‌افکن شانه‌ای زره. همین چرخه شما را مجبور می‌کند همیشه در حرکت و حمله باشید.",
        "سلاح‌ها با مدهای مختلف کارکرد متفاوتی پیدا می‌کنند و برخی دشمنان نقاط ضعف قابل‌تخریب دارند. بخش‌های پلتفرمر و پرش دوگانه هم به جابه‌جایی در میدان نبرد تنوع داده‌اند. موسیقی متال میک گوردون هم انرژی هر درگیری را دوچندان می‌کند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "حالت‌های بازی",
      "paragraphs": [
        "کمپین تک‌نفره بخش اصلی بازی است. Battlemode هم حالتی آنلاین است که در آن یک بازیکن در نقش اسلیر در برابر دو بازیکن در نقش شیاطین قرار می‌گیرد."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر فقط کمپین را می‌خواهید، اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. برای Battlemode ظرفیت ۲ یا ۳ و معمولاً PS Plus لازم است. ظرفیت ۲ هم آنلاین و هم آفلاین را پوشش می‌دهد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('hades-ii', $j${
  "intro": "Hades II ادامه Hades، روگ‌لایک برنده جوایز متعدد استودیو Supergiant Games است. این بار شاهزاده‌ای جاودانه از جهان زیرین، با جادوی سیاه و پشتیبانی خدایان المپ، به جنگ تایتان زمان می‌رود. بازی دنیایی بزرگ‌تر و عمیق‌تر از اسطوره‌های یونانی را با همان مبارزات سریع و روایت هوشمندانه نسخه اول ترکیب می‌کند.",
  "suits": ["طرفداران روگ‌لایک", "علاقه‌مندان اسطوره‌های یونان", "بازیکنانی که اکشن سریع دوست دارند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شخصیت اصلی ملینوئه، دختر هادس و خواهر زاگرئوس، است. کرونوس، تایتان زمان، به جهان زیرین حمله کرده و خانواده‌اش را اسیر کرده است. ملینوئه که زیر نظر الهه جادو آموزش دیده، برای شکست دادن او راهی سفری خطرناک می‌شود.",
        "مثل نسخه اول، داستان با هر شکست و پیروزی کمی جلوتر می‌رود؛ بعد از هر بار مرگ به پایگاه برمی‌گردید، با شخصیت‌ها گفت‌وگو می‌کنید و رابطه‌ها عمیق‌تر می‌شوند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "هر تلاش، یا «ران»، از اتاق‌هایی پر از دشمن تشکیل شده و در طول مسیر از خدایان المپ برکت‌هایی می‌گیرید که حمله‌ها و توانایی‌هایتان را تقویت می‌کنند. ترکیب این برکت‌ها با سلاح انتخابی، هر ران را منحصربه‌فرد می‌کند.",
        "ملینوئه علاوه بر سلاح، از جادو و توانایی‌های ویژه استفاده می‌کند و بازی دو مسیر متفاوت دارد: یکی به اعماق جهان زیرین و دیگری به سطح زمین و به سوی المپ. ارتقاهای دائمی هم میان ران‌ها شما را قوی‌تر می‌کنند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Hades II کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. قیمت روش‌های مختلف را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('mortal-shell-enhanced-edition', $j${
  "intro": "Mortal Shell یک نقش‌آفرینی اکشن سخت و تاریک از استودیو مستقل Cold Symmetry است که از سبک سولزلایک الهام گرفته اما ایده خاص خودش را دارد: شما موجودی بی‌شکل هستید که می‌تواند در بدن جنگجویان مرده حلول کند. Enhanced Edition نسخه بهینه‌شده بازی برای کنسول‌های نسل جدید است.",
  "suits": ["طرفداران سولزلایک", "بازیکنان چالش‌طلب", "علاقه‌مندان فضای تاریک"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شما به شکل پوسته‌ای خالی در دنیایی ویران بیدار می‌شوید؛ جایی که باقی‌مانده بشریت در حال پوسیدن است. به فرمان موجودی مرموز به نام «پدر تاریک»، باید پرستشگاه‌های پنهان پیروان مؤمن را پیدا کنید.",
        "داستان مثل بسیاری از بازی‌های این سبک، با اشاره‌ها و جزئیات محیطی روایت می‌شود و کشف آن بر عهده خود شماست."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "به‌جای ساخت شخصیت با امتیاز، چند «پوسته» یا جنگجوی مرده پیدا می‌کنید که هر کدام سبک خاص خودشان را دارند؛ یکی مقاوم و کند است و دیگری چابک و شکننده. می‌توانید میان آن‌ها جابه‌جا شوید و هر کدام را جداگانه ارتقا دهید.",
        "مهم‌ترین توانایی، «سخت شدن» است: در هر لحظه، حتی وسط حمله، بدنتان را به سنگ تبدیل می‌کنید تا ضربه دشمن را دفع کنید. تعداد سلاح‌ها کم اما هر کدام عمیق و متفاوت‌اند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Mortal Shell کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. قیمت روش‌های مختلف را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('blades-of-fire', $j${
  "intro": "Blades of Fire یک اکشن ماجرایی تازه از استودیو اسپانیایی MercurySteam است؛ سازندگان Castlevania: Lords of Shadow و Metroid Dread. ویژگی اصلی بازی ساختن سلاح‌هاست: در دنیایی که فولاد به سنگ تبدیل شده، شما باید سلاح‌هایتان را در کوره‌ای افسانه‌ای و با دست خودتان بسازید.",
  "suits": ["طرفداران اکشن فانتزی", "علاقه‌مندان مبارزات سنگین و تاکتیکی", "بازیکنانی که ساخت‌وساز دوست دارند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "ملکه تازه‌تاج‌گذاری‌شده نریا طلسمی قدرتمند به کار برده که فولاد را به سنگ تبدیل می‌کند و تنها سپاهیان هیولاوار او سلاح‌هایی از فلز الهی در دست دارند. شما در نقش آران د لیرا، جنگجویی که به کوره «سازندگان»، غول‌های افسانه‌ای دوران کهن، دست پیدا می‌کند، برای شکستن این طلسم راهی سفر می‌شوید.",
        "در این مسیر نوجوانی دانشمند همراه آران است که ماجراها را ثبت می‌کند و به روایت داستان رنگ انسانی می‌دهد."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "در کوره، سلاح را بخش‌به‌بخش طراحی می‌کنید و با یک بازی کوچک چکش‌کاری، کیفیت آن را تعیین می‌کنید. هر سلاح در اثر استفاده فرسوده می‌شود و باید تیز یا تعمیر شود.",
        "مبارزه جهت‌دار است: می‌توانید ضربه را به سر، تنه یا بخش‌های مختلف بدن دشمن هدایت کنید و نوع ضربه، برشی، کوبشی یا فروکنندگی، در برابر زره‌های مختلف اثر متفاوتی دارد. همین مبارزه را سنگین و تاکتیکی می‌کند."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Blades of Fire کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('pga-tour-2k25', $j${
  "intro": "PGA Tour 2K25 جدیدترین نسخه سری شبیه‌ساز گلف 2K است که استودیو HB Studios آن را ساخته است. بازی با گلف‌بازان برتر جهان، زمین‌های تاریخی و مشهور و تورنمنت‌های بزرگ، تجربه‌ای جدی و دقیق از گلف حرفه‌ای را روی PS5 ارائه می‌کند.",
  "suits": ["طرفداران گلف", "علاقه‌مندان شبیه‌سازهای ورزشی", "بازیکنانی که بازی آرام و دقیق دوست دارند"],
  "sections": [
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "ضربه زدن در این بازی با حرکت آنالوگ دسته انجام می‌شود و قدرت، زاویه و سرعت ضربه همه در نتیجه اثر دارند. باید باد، شیب زمین، نوع چمن و انتخاب چوب را در نظر بگیرید تا توپ دقیقاً به جای دلخواه برسد.",
        "برای تازه‌واردها سطح‌های مختلف دشواری و کمک‌های نمایشی در نظر گرفته شده و حرفه‌ای‌ها می‌توانند با تنظیمات سخت‌تر، چالش واقعی‌تری تجربه کنند."
      ]
    },
    {
      "heading": "حالت‌های بازی",
      "paragraphs": [
        "در حالت MyCAREER گلف‌باز خودتان را می‌سازید، مهارت‌هایش را ارتقا می‌دهید و در تورنمنت‌های تور حرفه‌ای به رقابت می‌پردازید. حالت‌های آنلاین هم برای رقابت با بازیکنان دیگر وجود دارد و ابزار طراحی زمین به شما امکان می‌دهد زمین‌های اختصاصی بسازید و به اشتراک بگذارید."
      ]
