      ]
    }
  ]
}$j$),

('truck-and-logistics-simulator', $j${
  "intro": "Truck & Logistics Simulator یک شبیه‌ساز حمل‌ونقل سنگین از استودیو Simula Games است. در این بازی تنها رانندگی مهم نیست؛ باید بار را درست بارگیری کنید، آن را ایمن ببندید و در دنیایی بزرگ و باز به مقصد برسانید. بازی از حالت چندنفره میان‌پلتفرمی تا ۲۴ بازیکن هم پشتیبانی می‌کند.",
  "suits": ["علاقه‌مندان شبیه‌سازی", "طرفداران کامیون و ماشین‌آلات سنگین", "بازی کاروانی با دوستان"],
  "sections": [
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "کار را با جابه‌جایی پالت‌ها با لیفتراک و بارگیری ون‌های کوچک شروع می‌کنید و کم‌کم به بارگیری کانتینرهای سنگین با تله‌هندلر روی تریلرها می‌رسید. بیش از ۳۰ وسیله نقلیه مختلف، از خودروهای سبک و لیفتراک تا لودر و کامیون‌های سنگین، در اختیار شماست.",
        "هر مأموریت چالش‌های خاص خودش را دارد و بارهای بزرگ و خاص، برنامه‌ریزی مسیر و مهارت رانندگی دقیق می‌طلبند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "بازی با دوستان",
