('marvels-midnight-suns-enhanced-edition', $j${
  "intro": "Marvel's Midnight Suns یک نقش‌آفرینی تاکتیکی از استودیو Firaxis، سازنده سری XCOM، است که قهرمانان مارول را در نبردی با نیروهای اهریمنی گرد هم می‌آورد. بازی مبارزات نوبتی مبتنی بر کارت را با بخش نقش‌آفرینی و روابط میان شخصیت‌ها ترکیب می‌کند. Enhanced Edition نسخه بازی برای کنسول‌های نسل جدید است.",
