('god-of-war-laufey', $j${
  "intro": "God of War: Laufey بازی اکشن ماجرایی تازه استودیو Santa Monica برای PS5 است که هنوز منتشر نشده و تاریخ عرضه آن برای اوایل سال ۲۰۲۷ اعلام شده است. این بار تمرکز از کریتوس برداشته شده و قهرمان ماجرا لافی، یا همان فِی، همسر کریتوس و مادر آتریوس است.",
