        "خیلی زود معلوم می‌شود که ماشین‌ها و اندرویدها آن‌قدرها هم که به نظر می‌رسد ساده نیستند. داستان چند پایان دارد و برای درک کامل آن، باید بازی را چند بار و از دید شخصیت‌های مختلف تجربه کنید؛ هر دور، بخش تازه‌ای از حقیقت را نشان می‌دهد."
